// Parse prospect JSON from each issue description
const issues = $input.all();
const prospects = [];

for (const item of issues) {
  const issue = item.json;
  let prospect;
  try {
    prospect = JSON.parse(issue.description || '{}');
  } catch {
    prospect = {};
  }

  // Skip suppressed or do_not_contact
  if (prospect.do_not_contact || prospect.suppressed) continue;
  if ((prospect.followup_count || 0) >= 2) continue;

  prospects.push({
    issue_id: issue.id,
    issue_title: issue.title,
    name: prospect.name || 'Unknown',
    company: prospect.company || 'Unknown',
    title: prospect.title || '',
    industry: prospect.industry || '',
    lane: prospect.lane || 'buyer',
    persona: prospect.persona || '',
    signal_type: prospect.signal_type || 'none',
    signal_notes: prospect.signal_notes || '',
    linkedin_url: prospect.linkedin_url || '',
    channel: prospect.channel || 'linkedin_dm',
    metric: prospect.metric || '50+',
  });
}

return prospects.map(p => ({json: p}));

// Classify pain bucket using rule-based matching (no LLM)
const prospect = $input.item.json;
const title = (prospect.title || '').toLowerCase();
const signals = (prospect.signal_notes || '').toLowerCase();
const industry = (prospect.industry || '').toLowerCase();

// Classification rules
let pain_bucket = 'review_velocity_gap'; // default

const complianceSignals = ['soc 2', 'audit', 'compliance', 'evidence', 'regulated', 'hipaa', 'fedramp', 'iso'];
const governanceSignals = ['ai code', 'copilot', 'code generation', 'proportional', 'cursor'];
const regulatorySignals = ['audit prep', 'soc 2 type ii', 'continuous monitoring', 'iso 27001'];
const velocitySignals = ['pr volume', 'review bottleneck', 'slow merges', 'backlog'];

if (regulatorySignals.some(s => signals.includes(s) || title.includes(s))) {
  pain_bucket = 'regulatory_readiness_gap';
} else if (complianceSignals.some(s => signals.includes(s) || title.includes(s))) {
  pain_bucket = 'evidence_chain_gap';
} else if (governanceSignals.some(s => signals.includes(s) || title.includes(s))) {
  pain_bucket = 'semantic_governance_gap';
} else {
  pain_bucket = 'review_velocity_gap';
}

// Select framing angle by lane/persona
let angle = 'direct';
const persona = (prospect.persona || '').toLowerCase();
if (['consultant', 'vciso', 'advisor'].some(p => persona.includes(p) || prospect.lane === 'connector')) {
  angle = 'consultant';
} else if (['devsecops', 'platform', 'developer'].some(p => persona.includes(p) || prospect.lane === 'builder')) {
  angle = 'platform';
} else if (['compliance', 'grc', 'audit'].some(p => persona.includes(p) || title.includes(p))) {
  angle = 'compliance';
}

return [{json: {...prospect, pain_bucket, angle}}];

// Load templates and fill with prospect data
const fs = require('fs');
const prospect = $input.item.json;

// Templates are baked into the workflow as a static object
// (In production, load from a shared volume or HTTP endpoint)
const templates = $env.OUTREACH_TEMPLATES ? JSON.parse($env.OUTREACH_TEMPLATES) : null;

let template;
if (templates && templates.templates) {
  const bucket = templates.templates[prospect.pain_bucket];
  if (bucket) {
    template = bucket[prospect.angle];
  }
}

if (!template) {
  // No template match -- flag for LLM fallback
  return [{json: {...prospect, template_match: false, needs_llm: true}}];
}

// Fill template variables
const fill = (text) => text
  .replace(/{name}/g, prospect.name)
  .replace(/{company}/g, prospect.company)
  .replace(/{title}/g, prospect.title)
  .replace(/{signal}/g, prospect.signal_notes)
  .replace(/{metric}/g, prospect.metric);

const draft = [
  fill(template.hook),
  '',
  fill(template.pain),
  '',
  fill(template.value),
  '',
  fill(template.cta),
  '',
  template.signoff
].join('\n');

// Slop check (banned words)
const slopWords = ['delve', 'leverage', 'paradigm', 'synergy', 'revolutionize', 'transform', 'unlock', 'supercharge', 'empower', 'game-changing', 'cutting-edge', 'holistic', 'robust', 'seamless', 'innovative'];
const draftLower = draft.toLowerCase();
const slopHits = slopWords.filter(w => draftLower.includes(w));
const slop_pass = slopHits.length === 0;

// Word count
const word_count = draft.split(/\s+/).length;

return [{json: {
  ...prospect,
  template_match: true,
  needs_llm: false,
  draft,
  pain_bucket: prospect.pain_bucket,
  angle: prospect.angle,
  slop_pass,
  slop_hits: slopHits,
  word_count,
  channel: prospect.channel,
}}];

